def solve(facts):
    alphabet = tuple(dict.fromkeys(facts['alphabet']))
    length = facts['length']
    modulus = facts['modulus']
    residue = facts['residue']
    low, high = facts['sum_min'], facts['sum_max']
    target, required = facts['target_digit'], facts['target_count']
    states = {(None, 0, 0, 0): 1}
    for position in range(length):
        following = {}
        for (last, remainder, digit_sum, copies), count in states.items():
            for digit in alphabet:
                if digit == last:
                    continue
                new_sum = digit_sum + digit
                new_copies = copies + int(digit == target)
                if new_sum > high or new_copies > required:
                    continue
                key = (digit, (10 * remainder + digit) % modulus, new_sum, new_copies)
                following[key] = following.get(key, 0) + count
        states = following
    count = 0
    total = 0
    for (last, remainder, digit_sum, copies), multiplicity in states.items():
        if remainder == residue and low <= digit_sum <= high and copies == required:
            count += multiplicity
            total += multiplicity * digit_sum
    return {'count': count, 'digit_sum_total': total}

def check(answer, facts):
    alphabet = tuple(dict.fromkeys(facts['alphabet']))
    length = facts['length']
    count = 0
    total = 0
    for digits in product(alphabet, repeat=length):
        if any(digits[i] == digits[i + 1] for i in range(length - 1)):
            continue
        if sum(d == facts['target_digit'] for d in digits) != facts['target_count']:
            continue
        digit_sum = sum(digits)
        if not facts['sum_min'] <= digit_sum <= facts['sum_max']:
            continue
        value = sum(d * pow(10, length - 1 - i) for i, d in enumerate(digits))
        if value % facts['modulus'] == facts['residue']:
            count += 1
            total += digit_sum
    return isinstance(answer, dict) and answer == {'count': count, 'digit_sum_total': total}
